// ── INFINITY HEALS COMMISSION STRUCTURE (CONFIDENTIAL) ──
const COMMISSION = {
  ethical_app: 0.16,    // 16% Fee Cut from MRP — Ethical medicines for IH App
  generic_app: 0.32,    // 32% Fee Cut — Generic medicines sold via App / Medical Store
  ethical_doc: 0.08,    // 8% Fee goes to Doctor — on ethical medicine
  generic_doc: 0.16,    // 16% Fee goes to Doctor — on generic medicine
  labtest_app: 0.32,    // 32% Fee deducted — Lab Tests IN App
  labtest_doc: 0.16,    // 16% goes to Doctor — on Lab Test
  doctor_fee_app: 0.16, // 16% Fee deducted — from Doctor's Consultation Fee IN App
  radiology_app: 0.32,  // 32% Fee deducted — MRI, Ultrasound, X-Ray, Radiology (Platform Fee)
  radiology_doc: 0.16,  // 16% goes to Doctor — on Radiology tests
  other_app: 0.32,      // 32% Fee deducted — Other tests (Platform Fee)
  other_doc: 0.16,      // 16% goes to Doctor — Other tests
  loyalty_per_100: 1,   // 1 Gold Coin per ₹100 spent by patient
};
// Helper: App price from MRP
function calcAppPrice(mrp, type) {
  if(type==="generic") return Math.round(mrp*(1-COMMISSION.generic_app));
  if(type==="labtest") return Math.round(mrp*(1-COMMISSION.labtest_app));
  if(type==="radiology") return Math.round(mrp*(1-COMMISSION.radiology_app));
  if(type==="docfee") return Math.round(mrp*(1-COMMISSION.doctor_fee_app));
  return Math.round(mrp*(1-COMMISSION.ethical_app)); // default ethical
}
// Helper: Doctor earning from MRP
function calcDocEarning(mrp, type) {
  if(type==="generic") return Math.round(mrp*COMMISSION.generic_doc);
  if(type==="labtest") return Math.round(mrp*COMMISSION.labtest_doc);
  if(type==="radiology") return Math.round(mrp*COMMISSION.radiology_doc);
  if(type==="other") return Math.round(mrp*COMMISSION.other_doc);
  return Math.round(mrp*COMMISSION.ethical_doc); // ethical
}
// Gold coins from spending
function calcCoins(amount) { return Math.floor(amount/100)*COMMISSION.loyalty_per_100; }



