// Load Firebase dynamically
let fbAuth = null, fbDb = null, fbStorage = null, fbGoogle = null;
const loadFirebase = async () => {
  if (fbAuth) return { auth: fbAuth, db: fbDb, storage: fbStorage };
  try {
    const { initializeApp, getApps } = await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js");
    const { getAuth, signInWithPopup, GoogleAuthProvider, signInWithEmailAndPassword,
            createUserWithEmailAndPassword, onAuthStateChanged, signOut } =
      await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js");
    const { getFirestore, doc, setDoc, getDoc, collection, addDoc, serverTimestamp, getDocs, query, where, orderBy } =
      await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js");
    const { getStorage, ref, uploadBytes, getDownloadURL } =
      await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-storage.js");
    const { getFunctions, httpsCallable } =
      await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-functions.js");
    const { RecaptchaVerifier: RV, signInWithPhoneNumber: SWPN } =
      await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js");
    const app = getApps().length ? getApps()[0] : initializeApp(FB_CONFIG);
    fbAuth = getAuth(app);
    fbDb = getFirestore(app);
    fbStorage = getStorage(app);
    fbGoogle = new GoogleAuthProvider();
    const fbFns = getFunctions(app, "asia-south1");
    return { auth: fbAuth, db: fbDb, storage: fbStorage, functions: fbFns,
             signInWithPopup, GoogleAuthProvider: fbGoogle,
             signInWithEmailAndPassword, createUserWithEmailAndPassword,
             onAuthStateChanged, signOut,
             RecaptchaVerifier: RV, signInWithPhoneNumber: SWPN,
             httpsCallable,
             doc, setDoc, getDoc, collection, addDoc, serverTimestamp, getDocs, query, where, orderBy,
             ref, uploadBytes, getDownloadURL };
  } catch(e) { return null; }
};

// ── CLOUD FUNCTION CALLER HELPER ──
async function ihCall_CF(fnName, data){
  try{
    var fb = await loadFirebase();
    if(!fb || !fb.httpsCallable || !fb.functions) return null;
    var fn = fb.httpsCallable(fb.functions, fnName);
    var result = await fn(data||{});
    return result.data;
  }catch(e){
    console.warn("CF "+fnName+" error:", e.message||e);
    return null;
  }
}

