// Universal YouTube Player - IFRAME embedded player
function YTPlayer({ytId,title,height=215,onClose}){
  const open=()=>{ window.open(`https://www.youtube.com/watch?v=${ytId}`,"_blank"); };
  return(
    <div style={{background:"#0f172a",borderRadius:14,overflow:"hidden",border:"2px solid #38bdf8",cursor:"pointer"}} onClick={open}>
      <div style={{position:"relative",height:height,background:"#000"}}>
        <img src={`https://img.youtube.com/vi/${ytId}/mqdefault.jpg`} alt={title||"video"}
          style={{width:"100%",height:"100%",objectFit:"cover",opacity:0.75,display:"block"}}
          onError={e=>{e.currentTarget.src=`https://img.youtube.com/vi/${ytId}/sddefault.jpg`;}}/>
        <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:8}}>
          <div style={{width:64,height:64,borderRadius:"50%",background:"rgba(255,0,0,0.9)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 20px rgba(255,0,0,0.5)"}}>
            <svg viewBox="0 0 24 24" width="28" height="28" fill="white"><path d="M8 5v14l11-7z"/></svg>
          </div>
          <div style={{background:"rgba(0,0,0,0.75)",borderRadius:20,padding:"5px 14px",fontSize:11,fontWeight:700,color:"#fff"}}>▶ Tap to Play</div>
        </div>
        {onClose&&<button onClick={e=>{e.stopPropagation();onClose();}} style={{position:"absolute",top:8,right:8,background:"rgba(0,0,0,0.7)",border:"none",borderRadius:"50%",width:30,height:30,color:"#fff",cursor:"pointer",fontSize:14,fontFamily:"inherit",zIndex:10}}>✕</button>}
      </div>
      <div style={{padding:"8px 12px",display:"flex",alignItems:"center",gap:8}} onClick={e=>e.stopPropagation()}>
        <div style={{flex:1,fontSize:11,fontWeight:600,color:"#fff",lineHeight:1.3}}>{title}</div>
        <button onClick={open} style={{background:"#ef4444",border:"none",borderRadius:8,padding:"5px 12px",fontSize:10,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit",flexShrink:0}}>▶ Play</button>
        {onClose&&<button onClick={onClose} style={{background:"#374151",border:"none",borderRadius:"50%",width:28,height:28,color:"#fff",cursor:"pointer",fontSize:12,fontFamily:"inherit"}}>✕</button>}
      </div>
    </div>
  );
}

