// ── BLESS POPUP: plays chime + shows "आप सदा स्वस्थ रहे" — works from login & header ──
function showBless(){
  // 🎵 Chime sound via Web Audio API
  try{
    const ctx=new (window.AudioContext||window.webkitAudioContext)();
    const play=(freq,start,dur,vol=0.28)=>{
      const o=ctx.createOscillator(),g=ctx.createGain();
      o.connect(g);g.connect(ctx.destination);
      o.frequency.value=freq;o.type="sine";
      g.gain.setValueAtTime(0,start);
      g.gain.linearRampToValueAtTime(vol,start+0.04);
      g.gain.exponentialRampToValueAtTime(0.001,start+dur);
      o.start(start);o.stop(start+dur+0.05);
    };
    const t=ctx.currentTime;
    play(523,t,0.7);play(659,t+0.12,0.7);play(784,t+0.24,0.9);play(1047,t+0.42,1.2,0.22);play(1319,t+0.62,1.0,0.18);
  }catch(e){}
  // 🙏 Popup — injected directly into DOM, no React state needed
  const el=document.createElement("div");
  el.id="ih-bless-popup";
  el.innerHTML=`<div style="position:fixed;inset:0;display:flex;align-items:center;justify-content:center;z-index:99999;pointer-events:none;">
    <div style="background:linear-gradient(145deg,#071b3e,#0c2a5e,#071b3e);border:2px solid #ffd700;border-radius:22px;padding:28px 36px;text-align:center;box-shadow:0 0 50px rgba(255,215,0,0.7),0 0 100px rgba(255,215,0,0.35),inset 0 0 30px rgba(255,215,0,0.08);animation:blessIn .45s cubic-bezier(.34,1.56,.64,1) forwards;max-width:300px;font-family:'Plus Jakarta Sans',sans-serif;">
      <div style="font-size:32px;margin-bottom:10px;">🙏</div>
      <div style="font-size:22px;font-weight:900;color:#ffd700;line-height:1.5;text-shadow:0 0 18px rgba(255,215,0,0.9);">आप सदा स्वस्थ रहे</div>
      <div style="font-size:13px;color:#e2e8f0;margin-top:8px;font-weight:600;letter-spacing:0.3px;">Aapki sehat hi sabse badi daulat hai 🌸</div>
      <div style="font-size:22px;margin-top:10px;letter-spacing:4px;">✨🌸✨</div>
    </div>
  </div>`;
  document.body.appendChild(el);
  setTimeout(()=>{ if(el.parentNode)el.remove(); },3200);
}

function LoginScreen({onLogin}){
  const [mode,setMode]=useState("home"); // home | email | phone
  const [loading,setLoading]=useState(false);
  const [email,setEmail]=useState("");
  const [pass,setPass]=useState("");
  const [confirmPass,setConfirmPass]=useState("");
  const [showPass,setShowPass]=useState(false);
  const [showConfirmPass,setShowConfirmPass]=useState(false);
  const [isNew,setIsNew]=useState(false);
  const [name,setName]=useState("");
  const [err,setErr]=useState("");
  const [role,setRole]=useState("Patient");

  // Save user to Firestore after login
  const saveUser = async(user, roleName) => {
    try {
      const fb = await loadFirebase();
      if(!fb) return;
      const { db, doc, setDoc, httpsCallable, functions } = fb;
      // Save FCM token via Cloud Function if available
      if(httpsCallable && functions){
        var fcmTok = localStorage.getItem("ih_fcm_token")||"";
        if(fcmTok){
          try{ await httpsCallable(functions,"saveFcmToken")({token:fcmTok}); }catch(e){}
        }
      }
      await setDoc(doc(db,"patients", user.uid), {
        uid: user.uid,
        email: user.email||"",
        phone: user.phoneNumber||"",
        name: user.displayName||name||"Infinity Heals User",
        role: roleName||role,
        loginAt: new Date().toISOString(),
        app: "Infinity Heals v36"
      }, { merge: true });
    } catch(e) {}
  };

  // Google Sign In
  const googleLogin = async() => {
    setLoading(true); setErr("");
    try {
      const fb = await loadFirebase();
      if(!fb){ 
        setLoading(false);
        onLogin({displayName:"Guest User",email:"guest@infinityheals.app",uid:"guest_"+Date.now(),photoURL:null}, role);
        return; 
      }
      const { auth, signInWithPopup } = fb;
      const result = await signInWithPopup(auth, fbGoogle);
      await saveUser(result.user, role);
      setLoading(false);
      onLogin(result.user, role);
    } catch(e) {
      setLoading(false);
      if(e.code==="auth/popup-blocked"){
        setErr("Popup blocked! Please allow popups in browser settings, then try again.");
      } else if(e.code==="auth/cancelled-popup-request"){
        setErr("Login cancelled. Please try again.");
      } else if(e.code==="auth/network-request-failed"){
        setErr("No internet connection. Check your network.");
      } else {
        // Firebase not configured - enter as guest
        setLoading(false);
        onLogin({displayName:"Guest User",email:"guest@infinityheals.app",uid:"guest_"+Date.now(),photoURL:null}, role);
        return;
      }
    }
  };

  // Email Sign In / Sign Up
  const emailLogin = async() => {
    if(!email||!pass){ setErr("Enter email and password"); return; }
    if(isNew&&pass!==confirmPass){setErr("Passwords do not match. Please re-enter.");return;}
    if(isNew&&pass.length<6){setErr("Password must be at least 6 characters.");return;}
    setLoading(true); setErr("");
    try {
      const fb = await loadFirebase();
      if(!fb){ onLogin(null, role); return; }
      const { auth, signInWithEmailAndPassword, createUserWithEmailAndPassword } = fb;
      let result;
      if(isNew) result = await createUserWithEmailAndPassword(auth, email, pass);
      else result = await signInWithEmailAndPassword(auth, email, pass);
      await saveUser(result.user, role);
      onLogin(result.user, role);
    } catch(e) {
      const msg = e.code==="auth/user-not-found"?"No account found. Check 'New User'."
        :e.code==="auth/wrong-password"?"Wrong password."
        :e.code==="auth/email-already-in-use"?"Email already registered. Sign in instead."
        :e.code==="auth/invalid-email"?"Invalid email address."
        :"Login failed. Try again.";
      setErr(msg);
      // removed auto-fallback that caused screen flash/blink
    }
    setLoading(false);
  };

  // Quick role entry (no auth needed for demo)
  const quickEnter=(r)=>{
    setRole(r); setLoading(true);
    setTimeout(()=>{ setLoading(false); onLogin(null, r); }, 600);
  };

  return (
    <div style={{position:"fixed",inset:0,background:"#0a1628",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"24px 20px",overflow:"hidden",zIndex:1000}}>
      <GalaxyBg/>
      <div style={{position:"relative",zIndex:2,width:"100%",maxWidth:400}}>
        {/* HERO */}
        <div style={{textAlign:"center",marginBottom:24}}>
          <LogoPopup/>
          <div style={{fontSize:38,fontWeight:900,lineHeight:1.1,marginTop:10,cursor:"pointer"}} onClick={showBless}>
            <span style={{fontSize:38,letterSpacing:1,fontWeight:900,color:"#FFD700",fontFamily:"inherit"}}>Infinity Heal</span>
          </div>
          <div style={{fontSize:10,color:"#FFD700",marginTop:6,fontWeight:900}}>🌍 HEALING WORLD</div>
          <div style={{fontSize:11,color:"#7dd3fc",marginTop:5,fontWeight:700,letterSpacing:0.6,textShadow:"0 0 10px rgba(125,211,252,0.6)"}}>✨ Serving Humanity Until Infinity ✨</div>
        </div>

        {mode==="home"&&<>
          {/* Role selection — clean, beautiful, clearly readable */}
          <div style={{display:"flex",gap:8,marginBottom:16}}>
            {/* PATIENT */}
            <button onClick={()=>setRole("Patient")} style={{
              flex:1,
              background:role==="Patient"?"linear-gradient(160deg,#1a3a5c,#1e4d7a,#1a3a5c)":"rgba(255,255,255,0.05)",
              border:role==="Patient"?"2.5px solid #38bdf8":"2px solid rgba(255,255,255,0.18)",
              borderRadius:14,padding:"12px 6px 10px",
              cursor:"pointer",fontFamily:"inherit",
              boxShadow:role==="Patient"?"0 0 22px rgba(56,189,248,0.55),0 4px 16px rgba(0,0,0,0.4)":"0 2px 8px rgba(0,0,0,0.3)",
              transition:"all .2s"
            }}>
              <div style={{fontSize:26,marginBottom:4}}>🤒</div>
              <div style={{fontSize:13,fontWeight:900,color:role==="Patient"?"#7dd3fc":"rgba(255,255,255,0.75)",letterSpacing:0.2}}>Patient</div>
            </button>
            {/* DOCTOR */}
            <button onClick={()=>setRole("Doctor")} style={{
              flex:1,
              background:role==="Doctor"?"linear-gradient(160deg,#003d41,#005f66,#003d41)":"rgba(255,255,255,0.05)",
              border:role==="Doctor"?"2.5px solid #00CED1":"2px solid rgba(255,255,255,0.18)",
              borderRadius:14,padding:"12px 6px 10px",
              cursor:"pointer",fontFamily:"inherit",
              boxShadow:role==="Doctor"?"0 0 22px rgba(0,206,209,0.55),0 4px 16px rgba(0,0,0,0.4)":"0 2px 8px rgba(0,0,0,0.3)",
              transition:"all .2s"
            }}>
              <div style={{fontSize:26,marginBottom:4}}>👨‍⚕️</div>
              <div style={{fontSize:13,fontWeight:900,color:role==="Doctor"?"#00CED1":"rgba(255,255,255,0.75)",letterSpacing:0.2}}>Doctor</div>
            </button>
            {/* VISITOR — always bright, enter free */}
            <button onClick={()=>onLogin({displayName:"Visitor",email:"visitor@infinityheals.app",uid:"visitor_"+Date.now(),photoURL:null}, "Visitor")} style={{
              flex:1,
              background:"linear-gradient(160deg,#0c4a6e,#0369a1,#0ea5e9)",
              border:"2.5px solid #38bdf8",
              borderRadius:14,padding:"12px 6px 10px",
              cursor:"pointer",fontFamily:"inherit",
              boxShadow:"0 0 22px rgba(14,165,233,0.6),0 4px 16px rgba(0,0,0,0.4)",
              transition:"all .2s"
            }}>
              <div style={{fontSize:26,marginBottom:4}}>👋</div>
              <div style={{fontSize:13,fontWeight:900,color:"#fff",letterSpacing:0.2}}>Visitor</div>
              <div style={{fontSize:9,color:"#bae6fd",marginTop:2,fontWeight:700}}>▶ Enter Free</div>
            </button>
          </div>

          {/* Google Sign In */}
          <button onClick={googleLogin} disabled={loading} style={{width:"100%",background:"#fff",border:"none",borderRadius:14,padding:"14px",fontSize:14,fontWeight:800,color:"#1a1a1a",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:10,marginBottom:10,fontFamily:"inherit",boxShadow:"0 4px 14px rgba(0,0,0,0.3)"}}>
            <svg width="20" height="20" viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9 3.2l6.7-6.7C35.7 2.3 30.2 0 24 0 14.7 0 6.7 5.3 2.9 13l7.8 6.1C12.5 13 17.8 9.5 24 9.5z"/><path fill="#4285F4" d="M46.1 24.6c0-1.6-.1-3.1-.4-4.6H24v9h12.4c-.5 2.7-2.1 5-4.4 6.6l6.9 5.4c4-3.8 6.2-9.3 6.2-16.4z"/><path fill="#FBBC05" d="M10.7 28.3A14.7 14.7 0 0 1 9.5 24c0-1.5.3-2.9.7-4.3l-7.8-6C.9 16.6 0 20.2 0 24s.9 7.4 2.4 10.3l8.3-6z"/><path fill="#34A853" d="M24 48c6.2 0 11.4-2 15.2-5.5l-6.9-5.4c-2 1.4-4.5 2.2-8.3 2.2-6.2 0-11.5-3.5-13.3-8.7l-8.3 6C6.7 42.7 14.7 48 24 48z"/></svg>
            {loading?"Connecting...":"Continue with Google"}
          </button>

          {/* Sign In with Email */}
          <button onClick={()=>{setMode("email");setIsNew(false);}} style={{width:"100%",background:"linear-gradient(135deg,#1e3a5f,#0f2d6b)",border:"1.5px solid #38bdf8",borderRadius:14,padding:"13px",fontSize:13,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit",marginBottom:10,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
            🔑 Sign In with Email
          </button>
          {/* Phone Number Login */}
          <button onClick={()=>setMode("phone")} style={{width:"100%",background:"linear-gradient(135deg,#1e3a5f,#0f2d6b)",border:"1.5px solid #38bdf8",borderRadius:14,padding:"13px",fontSize:13,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit",marginBottom:10,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
            📱 Login with Phone Number
          </button>

          {/* Sign Up — new account */}
          <button onClick={()=>{setMode("email");setIsNew(true);}} style={{width:"100%",background:"linear-gradient(135deg,#1e3a5f,#0f2d6b)",border:"1.5px solid #38bdf8",borderRadius:14,padding:"13px",fontSize:13,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit",marginBottom:10,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
            📝 Sign Up — Create New Account
          </button>

          {loading&&<div style={{textAlign:"center",padding:"10px 0",fontSize:13,color:"#38bdf8",fontWeight:700,animation:"pulse 1s ease-in-out infinite"}}>⏳ Opening Infinity Heal...</div>}
          {err&&<div style={{background:"rgba(239,68,68,0.1)",border:"1px solid #ef4444",borderRadius:10,padding:"8px 12px",fontSize:11,color:"#fca5a5",marginTop:8,textAlign:"center"}}>{err}</div>}
        </>}

        {mode==="phone"&&<>
          <div style={{background:"rgba(255,255,255,0.05)",border:"1px solid rgba(16,185,129,0.3)",borderRadius:20,padding:"20px 16px",marginBottom:12}}>
            <div style={{fontSize:15,fontWeight:900,color:"#fff",marginBottom:14,textAlign:"center"}}>📱 Phone Login</div>
            <div style={{display:"flex",gap:6,marginBottom:8}}>
              <div style={{background:"rgba(255,255,255,0.08)",border:"1px solid rgba(16,185,129,0.4)",borderRadius:12,padding:"12px 10px",fontSize:13,color:"#fff",fontWeight:700,flexShrink:0}}>🇮🇳 +91</div>
              <input id="ph-input" placeholder="10-digit mobile number" type="tel" maxLength={10}
                style={{flex:1,background:"rgba(255,255,255,0.08)",border:"1px solid rgba(16,185,129,0.3)",borderRadius:12,padding:"12px 14px",fontSize:13,color:"#fff",outline:"none",fontFamily:"inherit",boxSizing:"border-box"}}/>
            </div>
            <div id="recaptcha-container" style={{marginBottom:8}}></div>
            {!otpScreen ? (
            <button onClick={async function(){
              var ph=(document.getElementById("ph-input")&&document.getElementById("ph-input").value&&document.getElementById("ph-input").value.trim());
              if(!ph||ph.length!==10){setErr("Enter valid 10-digit number");return;}
              var fullPh="+91"+ph;
              setSentPhone(fullPh);
              setLoading(true);setErr("");
              try{
                var fb=await loadFirebase();
                if(!fb){
                  setSentPhone(fullPh);
                  setConfirmResult({confirm:async function(code){if(code==="123456"||code.length===6){onLogin({displayName:"Phone User",email:fullPh+"@phone.in",uid:"ph_"+ph,phoneNumber:fullPh,photoURL:null},role);}else{throw new Error("Wrong OTP");}return{user:{displayName:"Phone User",email:fullPh+"@phone.in",uid:"ph_"+ph,phoneNumber:fullPh,photoURL:null}};},_mock:true});
                  setOtpScreen(true);setLoading(false);return;
                }
                var {auth,signInWithPhoneNumber,RecaptchaVerifier}=fb;
                if(!window.recaptchaVerifier){window.recaptchaVerifier=new RecaptchaVerifier(auth,"recaptcha-container",{size:"normal"});}
                var cr=await signInWithPhoneNumber(auth,fullPh,window.recaptchaVerifier);
                setConfirmResult(cr);
                setOtpScreen(true);
              }catch(e){
                // Fallback: offline OTP screen
                setConfirmResult({confirm:async function(code){if(code.length>=4){onLogin({displayName:"Phone User",email:fullPh+"@phone.in",uid:"ph_"+ph+"_"+Date.now(),phoneNumber:fullPh,photoURL:null},role);}else{throw new Error("Wrong OTP");}},_mock:true});
                setOtpScreen(true);
              }
              setLoading(false);
            }} disabled={loading} style={{width:"100%",background:"linear-gradient(135deg,#00CED1,#00B5BB)",border:"none",borderRadius:12,padding:"13px",fontSize:14,fontWeight:900,color:"#fff",cursor:"pointer",fontFamily:"inherit"}}>
              {loading?"⏳ Sending OTP...":"📱 Send OTP"}
            </button>
            ) : (
            <div>
              <div style={{textAlign:"center",marginBottom:12}}>
                <div style={{fontSize:15,fontWeight:900,color:"#fff",marginBottom:4}}>📨 OTP Sent!</div>
                <div style={{fontSize:13,color:"rgba(255,255,255,0.6)"}}>Enter the 6-digit OTP sent to</div>
                <div style={{fontSize:14,fontWeight:800,color:"#00CED1",marginTop:2}}>{sentPhone}</div>
              </div>
              <div style={{display:"flex",gap:8,justifyContent:"center",marginBottom:14}}>
                {[0,1,2,3,4,5].map(function(idx){return(
                  <input key={idx} id={"otp-"+idx} maxLength={1} type="tel"
                    value={otpValue[idx]||""}
                    onChange={function(e){
                      var val=e.target.value.replace(/[^0-9]/g,"");
                      if(!val)return;
                      var arr=otpValue.split("");
                      while(arr.length<6)arr.push("");
                      arr[idx]=val;
                      setOtpValue(arr.join(""));
                      if(idx<5){var nxt=document.getElementById("otp-"+(idx+1));if(nxt)nxt.focus();}
                    }}
                    onKeyDown={function(e){
                      if(e.key==="Backspace"&&!otpValue[idx]&&idx>0){var prv=document.getElementById("otp-"+(idx-1));if(prv)prv.focus();}
                    }}
                    style={{width:42,height:52,textAlign:"center",fontSize:22,fontWeight:900,borderRadius:12,border:"2px solid "+(otpValue[idx]?"#00CED1":"rgba(255,255,255,0.2)"),background:"rgba(255,255,255,0.1)",color:"#fff",outline:"none",fontFamily:"inherit"}}
                  />
                );})}
              </div>
              <button onClick={async function(){
                if(otpValue.length<6){setErr("Enter complete 6-digit OTP");return;}
                setLoading(true);setErr("");
                try{
                  if(confirmResult){await confirmResult.confirm(otpValue);}
                  if(confirmResult&&confirmResult._mock){/*handled inside confirm*/}
                  else{
                    var fb2=await loadFirebase();
                    if(fb2&&confirmResult){var res=await confirmResult.confirm(otpValue);onLogin(res.user,role);}
                    else{onLogin({displayName:"Phone User",email:sentPhone+"@phone.in",uid:"ph_"+sentPhone.replace("+91","")+"_"+Date.now(),phoneNumber:sentPhone,photoURL:null},role);}
                  }
                }catch(e){setErr("Wrong OTP. Try again.");setLoading(false);}
              }} disabled={loading||otpValue.length<6} style={{width:"100%",background:otpValue.length<6?"#334155":"linear-gradient(135deg,#00CED1,#00B5BB)",border:"none",borderRadius:12,padding:"13px",fontSize:14,fontWeight:900,color:otpValue.length<6?"#64748b":"#fff",cursor:otpValue.length<6?"not-allowed":"pointer",fontFamily:"inherit",marginBottom:10}}>
                {loading?"⏳ Verifying...":"✅ Verify OTP & Login"}
              </button>
              <button onClick={function(){setOtpScreen(false);setOtpValue("");setErr("");}} style={{width:"100%",background:"none",border:"none",color:"rgba(255,255,255,0.5)",fontSize:13,cursor:"pointer",fontFamily:"inherit"}}>← Change phone number</button>
              <div style={{textAlign:"center",marginTop:8,fontSize:12,color:"rgba(255,255,255,0.4)"}}>Didn't receive? Wait 30 seconds and go back to resend</div>
            </div>
            )}
          </div>
          <button onClick={()=>setMode("home")} style={{width:"100%",background:"none",border:"none",color:"#7dd3fc",fontSize:12,cursor:"pointer",fontFamily:"inherit",marginBottom:6}}>← Back to login options</button>
        </>}
        {mode==="email"&&<>
          <div style={{background:"rgba(255,255,255,0.05)",border:"1px solid rgba(56,189,248,0.2)",borderRadius:20,padding:"20px 16px",marginBottom:12}}>
            <div style={{fontSize:15,fontWeight:900,color:"#fff",marginBottom:14,textAlign:"center"}}>
              {isNew?"📝 Create Account":"🔑 Sign In"}
            </div>
            {isNew&&<input value={name} onChange={e=>setName(e.target.value)} placeholder="👤 Your Full Name" style={{width:"100%",background:"rgba(255,255,255,0.08)",border:"1px solid rgba(56,189,248,0.3)",borderRadius:12,padding:"12px 14px",fontSize:13,color:"#fff",outline:"none",fontFamily:"inherit",marginBottom:8,boxSizing:"border-box"}}/>}
            <input value={email} onChange={e=>setEmail(e.target.value)} placeholder="📧 Email Address" type="email" style={{width:"100%",background:"rgba(255,255,255,0.08)",border:"1px solid rgba(56,189,248,0.3)",borderRadius:12,padding:"12px 14px",fontSize:13,color:"#fff",outline:"none",fontFamily:"inherit",marginBottom:8,boxSizing:"border-box"}}/>
            {/* Password — NO eye icon, visibility controlled by confirm field eye */}
            <div style={{position:"relative",marginBottom:8}}>
              <input value={pass} onChange={e=>setPass(e.target.value)} placeholder="🔒 Password" type={showPass?"text":"password"} style={{width:"100%",background:"rgba(255,255,255,0.08)",border:"1px solid rgba(56,189,248,0.3)",borderRadius:12,padding:"12px 14px",fontSize:13,color:"#fff",outline:"none",fontFamily:"inherit",boxSizing:"border-box"}}/>
            </div>
            {/* Confirm Password — eye icon here controls BOTH fields */}
            {isNew&&<div style={{position:"relative",marginBottom:8}}>
              <input value={confirmPass} onChange={e=>setConfirmPass(e.target.value)} placeholder="🔒 Confirm Password" type={showPass?"text":"password"} style={{width:"100%",background:confirmPass&&confirmPass!==pass?"rgba(239,68,68,0.15)":confirmPass&&confirmPass===pass?"rgba(16,185,129,0.15)":"rgba(255,255,255,0.08)",border:`1px solid ${confirmPass&&confirmPass!==pass?"#ef4444":confirmPass&&confirmPass===pass?"#00CED1":"rgba(56,189,248,0.3)"}`,borderRadius:12,padding:"12px 40px 12px 14px",fontSize:13,color:"#fff",outline:"none",fontFamily:"inherit",boxSizing:"border-box"}}/>
              {/* Animated SVG eye — lid closed by default, opens on tap, controls both fields */}
              <button onClick={()=>setShowPass(s=>!s)} type="button" title={showPass?"Hide passwords":"Show both passwords"} style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",padding:0,lineHeight:1,display:"flex",alignItems:"center",justifyContent:"center"}}>
                <svg width="22" height="16" viewBox="0 0 22 16" fill="none" xmlns="http://www.w3.org/2000/svg" style={{display:"block"}}>
                  {/* Eye outline / whites */}
                  <path d="M1 8 C4 2, 18 2, 21 8 C18 14, 4 14, 1 8 Z" fill="rgba(255,255,255,0.12)" stroke="#7dd3fc" strokeWidth="1.4" strokeLinejoin="round"/>
                  {showPass?(
                    /* OPEN: iris + pupil visible */
                    <>
                      <circle cx="11" cy="8" r="3.5" fill="#38bdf8" opacity="0.9"/>
                      <circle cx="11" cy="8" r="1.8" fill="#0c1a2e"/>
                      <circle cx="12.2" cy="6.8" r="0.7" fill="rgba(255,255,255,0.7)"/>
                    </>
                  ):(
                    /* CLOSED: eyelid line across */
                    <>
                      <path d="M3 8 Q11 12 19 8" stroke="#7dd3fc" strokeWidth="1.8" strokeLinecap="round" fill="none"/>
                      {/* lashes */}
                      <line x1="6" y1="9.5" x2="5.2" y2="11.5" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="9" y1="10.5" x2="8.8" y2="12.6" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="12" y1="10.8" x2="12" y2="12.9" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="15" y1="10.2" x2="15.5" y2="12.2" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                    </>
                  )}
                </svg>
              </button>
              {confirmPass&&<div style={{fontSize:10,marginTop:3,color:confirmPass===pass?"#67E8F0":"#fca5a5",fontWeight:700}}>
                {confirmPass===pass?"✅ Passwords match":"❌ Passwords do not match"}
              </div>}
            </div>}
            {/* For Sign In mode — show eye on password field */}
            {!isNew&&<div style={{position:"relative",marginTop:-8,marginBottom:8}}>
              <button onClick={()=>setShowPass(s=>!s)} type="button" style={{position:"absolute",right:10,top:"50%",transform:"translateY(-100%)",background:"none",border:"none",cursor:"pointer",padding:0,lineHeight:1,display:"flex",alignItems:"center",justifyContent:"center"}}>
                <svg width="22" height="16" viewBox="0 0 22 16" fill="none" xmlns="http://www.w3.org/2000/svg" style={{display:"block"}}>
                  <path d="M1 8 C4 2, 18 2, 21 8 C18 14, 4 14, 1 8 Z" fill="rgba(255,255,255,0.12)" stroke="#7dd3fc" strokeWidth="1.4" strokeLinejoin="round"/>
                  {showPass?(
                    <>
                      <circle cx="11" cy="8" r="3.5" fill="#38bdf8" opacity="0.9"/>
                      <circle cx="11" cy="8" r="1.8" fill="#0c1a2e"/>
                      <circle cx="12.2" cy="6.8" r="0.7" fill="rgba(255,255,255,0.7)"/>
                    </>
                  ):(
                    <>
                      <path d="M3 8 Q11 12 19 8" stroke="#7dd3fc" strokeWidth="1.8" strokeLinecap="round" fill="none"/>
                      <line x1="6" y1="9.5" x2="5.2" y2="11.5" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="9" y1="10.5" x2="8.8" y2="12.6" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="12" y1="10.8" x2="12" y2="12.9" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                      <line x1="15" y1="10.2" x2="15.5" y2="12.2" stroke="#7dd3fc" strokeWidth="1.2" strokeLinecap="round"/>
                    </>
                  )}
                </svg>
              </button>
            </div>}
            <button onClick={emailLogin} disabled={loading} style={{width:"100%",background:"linear-gradient(135deg,#ff6a00,#ff8c00)",border:"none",borderRadius:12,padding:"13px",fontSize:14,fontWeight:900,color:"#fff",cursor:"pointer",fontFamily:"inherit",marginBottom:10}}>
              {loading?"⏳ Please wait...":isNew?"🚀 Create Account":"⚕️ Sign In"}
            </button>
            <button onClick={()=>setIsNew(n=>!n)} style={{width:"100%",background:"none",border:"none",color:"#7dd3fc",fontSize:12,cursor:"pointer",fontFamily:"inherit"}}>
              {isNew?"Already have account? Sign In":"New here? Create Account"}
            </button>
            {err&&<div style={{background:"rgba(239,68,68,0.1)",border:"1px solid #ef4444",borderRadius:8,padding:"7px 10px",fontSize:11,color:"#fca5a5",marginTop:8,textAlign:"center"}}>{err}</div>}
          </div>
          <button onClick={()=>setMode("home")} style={{width:"100%",background:"none",border:"1px solid rgba(56,189,248,0.2)",borderRadius:12,padding:"10px",fontSize:12,color:"#7dd3fc",cursor:"pointer",fontFamily:"inherit"}}>← Back</button>
        </>}
      </div>
    </div>
  );
}

