// ── SOCIAL + CONTENT FEED (𝕏 · Bytes · Research · I Follow · My Post) ──
function ContentFeedSection({T,dark,goTo}){
  const [tab,setTab]=useState(0);
  const [loading,setLoading]=useState(false);
  const [cache,setCache]=useState({});
  const [myPostText,setMyPostText]=useState("");
  const [myPosts,setMyPosts]=useState([
    {id:1,txt:"Completed 10,000 steps today! My doctor was right — walking is the best medicine.",likes:24,comments:8,time:"2h ago",liked:false},
  ]);

  const TABS=[
    {label:"𝕏",key:"x"},
    {label:"📰News",key:"news"},
    {label:"⚡Bytes",key:"bytes"},
    {label:"🔬Research",key:"research"},
    {label:"👥Follow",key:"follow"},
    {label:"📢 Ad",key:"mypost"},
  ];

  const PROMPTS={
    x:`Return a single real-style health post from an Indian doctor on X (Twitter). JSON object only: {user,handle,verified,avatar,time,txt,likes,retweets,replies,color}. color is a hex like #ef4444. No markdown.`,
    news:`Return a single recent Indian health news headline. JSON object only: {emoji,headline,source,time,summary,category,color}. summary under 80 chars. category is like "Policy","Research","Alert","Outbreak". color is hex. No markdown.`,
    bytes:`Return a single ultra-short health byte for Indian patients. JSON object: {emoji,title,body,tag,source}. Body under 100 chars. tag is a medical specialty. No markdown.`,
    research:`Return a single RECENT health research finding relevant to India 2024. JSON object: {emoji,title,journal,finding,date,impact}. Make it realistic. No markdown.`,
    follow:`Return a single health social media post from a doctor/patient someone follows. JSON: {user,handle,verified,avatar,platform,time,content,likes,comments,platform_icon}. platform_icon is 𝕏 or 📸. No markdown.`,
  };

  const STATIC_CONTENT={
    x:{user:"Dr. Priya Sharma",handle:"@drpriya_cardio",verified:true,avatar:"👩‍⚕️",time:"2h ago",txt:"🚨 MYTH BUSTED: Eggs do NOT raise bad cholesterol in healthy adults. 2024 AHA update confirms 1 egg/day is safe. Stop avoiding eggs — start avoiding ultra-processed foods! #HeartHealth #IndiaHealth",likes:2847,retweets:891,replies:124,color:"#ef4444"},
    news:{emoji:"🏥",headline:"ICMR approves India's first dengue vaccine for endemic regions",source:"Health Ministry India",time:"3h ago",summary:"New dengue vaccine approved for seropositive individuals aged 9-45 in high-burden states",category:"Policy",color:"#f97316"},
    bytes:{emoji:"💡",title:"Walking 10 min after meals cuts blood sugar by 22%",body:"A short post-meal walk is more effective than one long walk. Try it after every meal!",tag:"Diabetes",source:"Lancet 2024"},
    research:{emoji:"🔬",title:"Turmeric + Black Pepper combination boosts curcumin absorption by 2000%",journal:"Journal of Nutritional Science",finding:"Piperine in black pepper dramatically increases curcumin bioavailability — always pair haldi with kali mirch",date:"Mar 2024",impact:"Major for Ayurvedic research"},
    follow:{user:"Dr. Anoop Misra",handle:"@dranoopmisra",verified:true,avatar:"👨‍⚕️",platform:"X",time:"5h ago",content:"📢 India now has 101 million diabetics — world's largest. But 70% don't know they have it. Free test camps this Sunday at Apollo centres. Share please 🙏 #DiabetesIndia",likes:4120,comments:289,platform_icon:"𝕏"},
  };

  const fetchOne = async(key,force=false)=>{
    if(key==="mypost") return;
    if(!force && cache[key]) return;
    setLoading(true);
    let success=false;
    // Try Anthropic Claude first
    try{
      const controller=new AbortController();
      const timeout=setTimeout(()=>controller.abort(),6000);
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        signal:controller.signal,
        body:JSON.stringify({
          model:"claude-haiku-4-5-20251001",
          max_tokens:300,
          system:"You are a health content API. Return ONLY a valid JSON object, no markdown, no backticks, no explanation.",
          messages:[{role:"user",content:PROMPTS[key]}]
        })
      });
      clearTimeout(timeout);
      if(res.ok){
        const data = await res.json();
        const text = ((data.content&&data.content[0]&&data.content[0].text)||"{}").replace(/```json|```/g,"").trim();
        const parsed=JSON.parse(text);
        setCache(c=>({...c,[key]:parsed}));
        success=true;
      }
    }catch(e){}
    // Try Gemini as fallback
    if(!success){
      try{
        const GEMINI_KEY="AIzaSyCHx1Jxjoi6QaRAH-Ypt95RWqqpRLSJTwU";
        const controller=new AbortController();
        const timeout=setTimeout(()=>controller.abort(),6000);
        const res=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_KEY}`,{
          method:"POST",headers:{"Content-Type":"application/json"},signal:controller.signal,
          body:JSON.stringify({contents:[{role:"user",parts:[{text:`${PROMPTS[key]} Return ONLY valid JSON, no markdown.`}]}],generationConfig:{maxOutputTokens:300,temperature:0.9}})
        });
        clearTimeout(timeout);
        if(res.ok){
          const data=await res.json();
          const text=((data&&data.candidates&&data.candidates[0]&&data.candidates[0].content&&data.candidates[0].content.parts&&data.candidates[0].content.parts[0]&&data.candidates[0].content.parts[0].text)||"{}").replace(/```json|```/g,"").trim();
          const parsed=JSON.parse(text);
          setCache(c=>({...c,[key]:parsed}));
          success=true;
        }
      }catch(e){}
    }
    // Use curated static content as final fallback
    if(!success){
      setCache(c=>({...c,[key]:STATIC_CONTENT[key]||{error:true}}));
    }
    setLoading(false);
  };

  const handleTabClick=(i)=>{
    // Open each social tab as full-screen page
    goTo("socialfeed_"+TABS[i].key);
  };

  // Auto-load first tab on mount
  useEffect(()=>{ fetchOne("x"); },[]);

  const item = cache[TABS[tab].key] || null;

  const submitPost=()=>{
    if(!myPostText.trim()) return;
    setMyPosts(p=>[{id:Date.now(),txt:myPostText,likes:0,comments:0,time:"Just now",liked:false},...p]);
    setMyPostText("");
  };

  return(
    <div style={{marginBottom:8}}>
      {/* Tab strip - tapping opens full-screen */}
      <div style={{display:"flex",background:"linear-gradient(135deg,#0c1a3a,#1e3a5f)",border:"2px solid #1d4ed8",borderRadius:10,marginBottom:6,overflow:"hidden",height:36}}>
        {TABS.map((t,i)=>(
          <button key={i} onClick={()=>handleTabClick(i)}
            style={{flex:1,background:"transparent",border:"none",borderRight:i<TABS.length-1?"1px solid #dbeafe":"none",
              borderBottom:"3px solid transparent",
              padding:"0 2px",fontSize:10.5,fontWeight:700,
              color:"#e2e8f0",cursor:"pointer",whiteSpace:"nowrap",fontFamily:"inherit",
              height:"100%",display:"flex",alignItems:"center",justifyContent:"center",
              transition:"color .1s,border-color .1s",minWidth:0}}>
            {t.label}
          </button>
        ))}
      </div>
      {/* Preview card showing latest X post */}
      {cache["x"]&&!cache["x"].error&&(
        <div onClick={()=>goTo("socialfeed_x")} style={{background:"#fff",border:"2px solid #1e3a5f",borderRadius:12,padding:"4px 12px",cursor:"pointer",boxShadow:"0 2px 8px rgba(30,58,95,0.1)"}}>
          <div style={{display:"flex",gap:7,marginBottom:5,alignItems:"center"}}>
            <div style={{width:26,height:26,borderRadius:8,background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13}}>👨‍⚕️</div>
            <span style={{fontSize:11,fontWeight:800,color:"#0f172a"}}>{cache["x"].user||"Dr. Health"}</span>
            <span style={{fontSize:9,color:"#64748b",marginLeft:"auto"}}>Tap to expand ↗</span>
          </div>
          <div style={{fontSize:11,color:"#334155",lineHeight:1.55}}>{(cache["x"].txt||"Health tip of the day...").substring(0,120)}...</div>
        </div>
      )}
      {!cache["x"]&&(
        <div onClick={()=>goTo("socialfeed_x")} style={{background:"#fff",border:"2px solid #1e3a5f",borderRadius:12,padding:"6px 12px",cursor:"pointer",textAlign:"center"}}>
          <div style={{fontSize:13,fontWeight:700,color:"#0f172a"}}>📱 Health Social Feed</div>
          <div style={{fontSize:10,color:"#64748b",marginTop:3}}>Tap any tab to open full-screen feed ↗</div>
        </div>
      )}

    </div>
  );
}

