            {inp("email","Email Address","email","📧")}
            {inp("address","Full Lab Address","text","📍")}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:9}}>
              <input value={biz.city} onChange={e=>up("city",e.target.value)} placeholder="🏙️ City" style={{background:"rgba(255,255,255,0.08)",border:"1px solid rgba(16,185,129,0.35)",borderRadius:12,padding:"12px 14px",fontSize:12,color:"#fff",outline:"none",fontFamily:"inherit",boxSizing:"border-box"}}/>
              <input value={biz.state} onChange={e=>up("state",e.target.value)} placeholder="🗺️ State" style={{background:"rgba(255,255,255,0.08)",border:"1px solid rgba(16,185,129,0.35)",borderRadius:12,padding:"12px 14px",fontSize:12,color:"#fff",outline:"none",fontFamily:"inherit",boxSizing:"border-box"}}/>
            </div>
            {inp("pin","PIN Code","tel","📮")}
