    var extra=[];
    try{var raw=localStorage.getItem("ih_doctor_profile");if(raw){var dp=JSON.parse(raw);if(dp&&dp.name&&dp.speciality)extra=[{n:dp.name,s:dp.speciality,c:dp.city||"India",f:dp.fee||"On request",p:dp.phone||"",cl:dp.clinic||"Private Practice",e:"👨‍⚕️",col:"#22c55e",sr:true}];}}catch(x){}
    var all=extra.concat(BASE_DOCS);
    if(!spec)return all.slice(0,4);
    var m=all.filter(function(d){return d.s===spec||d.s.toLowerCase().includes(spec.toLowerCase())||spec.toLowerCase().includes(d.s.toLowerCase());});
    return m.length>0?m:all.slice(0,3);
