            {false&&"fee"==="x"&&(<div className="c3d" style={{background:T.card,border:"1.5px solid "+T.bor,borderRadius:14,padding:"14px"}}><div style={{fontSize:14,fontWeight:900,color:T.text,marginBottom:12}}>💰 Fee</div>{[{type:"In-Clinic Consultation",fee:urologistDoc.fee,note:"First visit"},{type:"Online Consultation",fee:"\u20B9400",note:"Video call"},{type:"Follow-up",fee:"\u20B9250",note:"Within 7 days"}].map(function(f,i){return(<div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"11px 0",borderBottom:i<2?"1px solid "+T.bor:"none"}}><div><div style={{fontSize:13,fontWeight:700,color:T.text}}>{f.type}</div><div style={{fontSize:10,color:T.sub}}>{f.note}</div></div><div style={{fontSize:16,fontWeight:900,color:"#ff8c00"}}>{f.fee}</div></div>);})}</div>)}
