function AbhaTab({T}){
  const steps=[
    {icon:"📱",title:"Download ABHA App",desc:"Download the ABHA (Ayushman Bharat Health Account) app from Google Play Store or Apple App Store, or visit abha.abdm.gov.in on your browser."},
    {icon:"🪪",title:"Enter Aadhaar / Mobile",desc:"Register using your Aadhaar card number or mobile number. An OTP will be sent for verification. Your identity is verified with UIDAI securely."},
    {icon:"🔢",title:"Get 14-Digit ABHA Number",desc:"After successful registration you receive a unique 14-digit ABHA Number — your lifelong digital health identity. Format: XX-XXXX-XXXX-XXXX."},
    {icon:"🆔",title:"Download ABHA Card",desc:"Download your digital ABHA card as PDF or image. Show it at any hospital, clinic, or lab for paperless health records and easy identification."},
    {icon:"🔗",title:"Link Health Records",desc:"Link all past hospital records, prescriptions, lab reports and insurance to your ABHA ID. Access them anytime, anywhere — no paper needed."},
    {icon:"🏥",title:"Use at Empanelled Hospitals",desc:"Show your ABHA card at any ABDM-empanelled hospital or clinic. Doctors can access your complete health history instantly with your permission."},
  ];
  const benefits=[
    {icon:"📋",label:"One Health ID for Life",desc:"Single 14-digit ID used across all hospitals, labs, pharmacies and insurers. No more carrying physical files."},
    {icon:"🔐",label:"Your Data, Your Control",desc:"You decide who can see your health records. Grant and revoke access to doctors or hospitals with a single tap."},
    {icon:"🌍",label:"Nationwide Acceptance",desc:"Valid at 1 lakh+ ABDM-empanelled hospitals and health facilities across all states of India."},
    {icon:"💊",label:"Digital Prescriptions",desc:"All prescriptions stored digitally. Never lose a prescription again — access it from your phone anytime."},
    {icon:"🧪",label:"Lab Reports Linked",desc:"Lab tests automatically linked to your ABHA account when done at registered labs. Share with any doctor instantly."},
    {icon:"🛡️",label:"Insurance Integration",desc:"Link your health insurance policy to ABHA. Claims processing becomes faster and paperless."},
    {icon:"📊",label:"Health Analytics",desc:"Track your health trends over time — BP, sugar, cholesterol history all in one timeline view."},
    {icon:"🆓",label:"Completely Free",desc:"ABHA registration and use is 100% free for all Indian citizens. No charges ever for creating or using your ABHA ID."},
  ];
  const faqs=[
    {q:"Who can create an ABHA account?",a:"Any Indian citizen can create an ABHA account. It is open to all age groups. For children, parents or guardians can create it on their behalf."},
    {q:"Is ABHA the same as Ayushman Bharat card?",a:"No. ABHA (Health Account ID) is a digital health identity for all citizens. Ayushman Bharat PM-JAY is a health insurance scheme only for eligible BPL families. ABHA is universal."},
    {q:"What if I lose my ABHA card?",a:"Your ABHA number is permanently stored digitally. Simply log in to the ABHA app or website to download a fresh copy. Nothing is lost."},
    {q:"Can I link records from private hospitals?",a:"Yes. Private hospitals registered with ABDM (Ayushman Bharat Digital Mission) can directly push records to your ABHA. You can also manually upload PDFs."},
    {q:"Is my health data safe?",a:"Yes. Data is stored on government-certified secure servers. Your records are encrypted and you have full consent control — no one can access without your explicit permission."},
    {q:"How to link Ayushman Bharat card with ABHA?",a:"Open the ABHA app → My Records → Link PM-JAY / Ayushman Bharat Card → Enter your Ayushman card number or verify via Aadhaar. Done!"},
  ];
  return(
    <div style={{padding:"10px 12px 80px"}}>
      <div style={{background:"linear-gradient(135deg,#0369a115,#0ea5e915)",border:"2px solid #0ea5e944",borderRadius:16,padding:"14px",marginBottom:12,textAlign:"center"}}>
        <div style={{fontSize:38}}>🆔</div>
        <div style={{fontSize:13,fontWeight:900,color:"#0ea5e9",marginTop:6}}>ABHA — Ayushman Bharat Health Account</div>
        <div style={{fontSize:11,color:T.sub,marginTop:4,lineHeight:1.5}}>India's national digital health identity · 14-digit unique health ID · Free for all citizens · Powered by ABDM · आयुष्मान भारत डिजिटल मिशन</div>
        <div style={{display:"flex",gap:8,justifyContent:"center",marginTop:10,flexWrap:"wrap"}}>
          {["14-Digit ID","Free Forever","100% Secure","Pan-India Valid"].map(b=><span key={b} style={{fontSize:11,background:"#0ea5e915",color:"#0ea5e9",borderRadius:6,padding:"2px 8px",fontWeight:700}}>{b}</span>)}
        </div>
      </div>
      <div style={{fontSize:15,fontWeight:900,color:T.text,marginBottom:8}}>📋 How to Create ABHA in 6 Steps</div>
      {steps.map((s,i)=>(
        <div key={i} style={{background:T.card,border:`1.5px solid ${T.bor}`,borderRadius:13,padding:"11px 13px",marginBottom:8,display:"flex",gap:10,alignItems:"flex-start"}}>
          <div style={{width:36,height:36,borderRadius:10,background:"#0ea5e915",border:"1.5px solid #0ea5e944",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0}}>{s.icon}</div>
          <div style={{flex:1}}>
            <div style={{fontSize:15,fontWeight:800,color:T.text,marginBottom:3}}>Step {i+1}: {s.title}</div>
            <div style={{fontSize:13,color:T.sub,lineHeight:1.5}}>{s.desc}</div>
          </div>
        </div>
      ))}
      <div style={{fontSize:15,fontWeight:900,color:T.text,marginBottom:8,marginTop:4}}>✨ Key Benefits of ABHA</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:12}}>
        {benefits.map((b,i)=>(
          <div key={i} style={{background:T.card,border:`1.5px solid #0ea5e922`,borderRadius:12,padding:"10px"}}>
            <div style={{fontSize:22,marginBottom:4}}>{b.icon}</div>
            <div style={{fontSize:15,fontWeight:800,color:T.text,marginBottom:3,lineHeight:1.3}}>{b.label}</div>
            <div style={{fontSize:13,color:T.sub,lineHeight:1.4}}>{b.desc}</div>
          </div>
        ))}
      </div>
      <div style={{fontSize:15,fontWeight:900,color:T.text,marginBottom:8}}>❓ Frequently Asked Questions</div>
      {faqs.map((f,i)=>(
        <div key={i} style={{background:T.card,border:`1.5px solid ${T.bor}`,borderRadius:12,padding:"11px 13px",marginBottom:8}}>
          <div style={{fontSize:15,fontWeight:800,color:"#0ea5e9",marginBottom:4}}>Q: {f.q}</div>
          <div style={{fontSize:13,color:T.sub,lineHeight:1.5}}>A: {f.a}</div>
        </div>
      ))}
      <div style={{display:"flex",gap:8,marginTop:4}}>
        <button onClick={()=>window.open("https://abha.abdm.gov.in","_blank","noopener,noreferrer")} style={{flex:1,background:"linear-gradient(135deg,#0ea5e9,#0369a1)",border:"none",borderRadius:12,padding:"13px",fontSize:12,fontWeight:900,color:"#fff",cursor:"pointer",fontFamily:"inherit"}}>🆔 Create ABHA ID → abha.abdm.gov.in</button>
        <button onClick={()=>window.open("https://apps.mgov.gov.in/descp.do?appid=1237&lang=en","_blank","noopener,noreferrer")} style={{background:"#ECFEFF",border:"2px solid #00CED1",borderRadius:12,padding:"13px 12px",fontSize:10,fontWeight:800,color:"#005F63",cursor:"pointer",fontFamily:"inherit",flexShrink:0}}>📱 App</button>
      </div>
    </div>
  );
}

