// Parse basic markdown: **bold**, *italic*, newlines → JSX
function mdToHtml(t){if(!t)return"";return t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\*\*([^*\n]+)\*\*/g,"<b>$1</b>").replace(/\*([^*\n]+)\*/g,"<i>$1</i>").replace(/\n/g,"<br/>");}

// ── GENETICS AI DNA IMAGE ICON ────────────────────────────────────────────
var DNA_IMG_SM  = "data:image/png;base64,";
var DNA_IMG_LG  = "data:image/png;base64,";

function GeneticsDNAIcon({h,bg,animated,pulse,size,large}){
  var ht = size||h||36;
  var src = (ht>28||large) ? DNA_IMG_LG : DNA_IMG_SM;
  var asp = 1024/559; // original image aspect ratio
  var w   = Math.round(ht * asp);

  // Motor/pulley spin: rotateY = spins on vertical axis like a wheel
  var spinAnim  = "dnaMotorSpin 5s linear infinite";
  var pulseAnim = "dnaPulse 2s ease-in-out infinite";
  var wrapStyle = {display:"inline-block",transformOrigin:"center",willChange:"transform"};
  if(animated&&pulse) wrapStyle.animation = spinAnim+", "+pulseAnim;
  else if(animated)   wrapStyle.animation = spinAnim;
  else if(pulse)      wrapStyle.animation = pulseAnim;

  return(
    <img
      src={src}
      alt="DNA"
      style={{
        width:w,
        height:ht,
        objectFit:"cover",
        objectPosition:"center",
        borderRadius:4,
        display:"inline-block",
        ...wrapStyle,
      }}
    />
  );
}


