// ── MEDICINE TIMING SCHEDULE ──
// Reads dose text and assigns each medicine to morning/noon/evening/night slots
function parseMedTiming(meds){
  var morning=[];var noon=[];var evening=[];var night=[];
  (meds||[]).forEach(function(med){
    // Use explicit slots if doctor set them via UI
    if(med.slots&&med.slots.length>0){
      var item={name:med.name,food:med.food||"after"};
      if(med.slots.indexOf("morning")>=0)morning.push(item);
      if(med.slots.indexOf("noon")>=0)noon.push(item);
      if(med.slots.indexOf("evening")>=0)evening.push(item);
      if(med.slots.indexOf("night")>=0)night.push(item);
      return;
    }
    var d=(med.dose||"").toLowerCase();
    var name=med.name||"";
    // detect count e.g. "2x/day", "3x/day", "4x/day", "once", "twice"
    var times=1;
    if(d.indexOf("4x")>=0||d.indexOf("4 times")>=0||d.indexOf("four times")>=0)times=4;
    else if(d.indexOf("3x")>=0||d.indexOf("3 times")>=0||d.indexOf("three times")>=0||d.indexOf("tds")>=0||d.indexOf("tid")>=0)times=3;
    else if(d.indexOf("2x")>=0||d.indexOf("twice")>=0||d.indexOf("2 times")>=0||d.indexOf("bd")>=0||d.indexOf("bid")>=0)times=2;
    else if(d.indexOf("once")>=0||d.indexOf("1x")>=0||d.indexOf("daily")>=0||d.indexOf("/day")>=0||d.indexOf("od")>=0)times=1;
    // detect food relation
    var empty=d.indexOf("empty")>=0||d.indexOf("fasting")>=0||d.indexOf("before")>=0||d.indexOf("empty stomach")>=0;
    var afterFood=d.indexOf("after food")>=0||d.indexOf("after meal")>=0||d.indexOf("after breakfast")>=0||d.indexOf("with food")>=0||d.indexOf("pc")>=0;
    var food=empty?"empty":"after";
    // detect specific time
    var nightOnly=d.indexOf("at night")>=0||d.indexOf("bedtime")>=0||d.indexOf("bed time")>=0||d.indexOf("night")>=0||d.indexOf("hs")>=0;
    var mornOnly=d.indexOf("morning")>=0||d.indexOf("breakfast")>=0;
    var item={name:name,food:food};
    if(nightOnly&&times===1){night.push(item);}
    else if(mornOnly&&times===1){morning.push(item);}
    else if(times===4){morning.push(item);noon.push(item);evening.push(item);night.push(item);}
    else if(times===3){morning.push(item);noon.push(item);night.push(item);}
    else if(times===2){morning.push(item);night.push(item);}
    else{morning.push(item);}
  });
  return{morning:morning,noon:noon,evening:evening,night:night};
}

function MedTimingSchedule({meds,color}){
  var timing=parseMedTiming(meds);
  var hasAny=timing.morning.length>0||timing.noon.length>0||timing.evening.length>0||timing.night.length>0;
  if(!hasAny)return null;
  var accent=color||"#22d3ee";
  var slots=[
    {icon:"🌅",label:"Morning",data:timing.morning,sub1:"Empty stomach",sub2:"After breakfast"},
    {icon:"☀️",label:"Noon",data:timing.noon,sub1:"Empty stomach",sub2:"After food"},
    {icon:"🌤️",label:"Evening",data:timing.evening,sub1:"4 PM",sub2:"6 PM / After snacks"},
    {icon:"🌙",label:"Night",data:timing.night,sub1:"Before food",sub2:"After food"},
  ];
  return(
    <div style={{background:"#e0fafa",border:"2px solid #00CED1",borderRadius:12,padding:"12px",marginBottom:8,marginTop:4}}>
      <div style={{fontSize:14,fontWeight:900,color:"#001a4d",marginBottom:10,letterSpacing:0.6,textShadow:"0 1px 4px rgba(0,26,77,0.18)"}}>⏰ MEDICINE SCHEDULE</div>
      {slots.map(function(slot,si){
        if(slot.data.length===0)return null;
        return(
          <div key={si} style={{marginBottom:10,paddingBottom:si<3?10:0,borderBottom:si<3?"1px solid #00CED155":"none"}}>
            <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}>
              <span style={{fontSize:18}}>{slot.icon}</span>
              <span style={{fontSize:16,fontWeight:900,color:"#001a4d",textShadow:"0 1px 3px rgba(0,26,77,0.15)"}}>{slot.label}</span>
              <span style={{fontSize:12,color:"#00868a",fontWeight:700}}>· {slot.sub1} / {slot.sub2}</span>
            </div>
            {slot.data.map(function(m,mi){
              return(
                <div key={mi} style={{display:"flex",alignItems:"center",justifyContent:"space-between",background:"#b2f0f0",border:"1px solid #00CED1",borderRadius:8,padding:"8px 12px",marginBottom:5}}>
                  <div style={{fontSize:14,fontWeight:800,color:"#001a4d",flex:1,textShadow:"0 1px 3px rgba(0,26,77,0.12)"}}>💊 {m.name}</div>
                  <div style={{fontSize:12,fontWeight:800,color:m.food==="empty"?"#7c4a00":m.food==="before"?"#3730a3":"#005a1f",flexShrink:0,marginLeft:8,background:m.food==="empty"?"#fde68a":m.food==="before"?"#ddd6fe":"#6ee7b7",border:m.food==="empty"?"1px solid #f59e0b":m.food==="before"?"1px solid #8b5cf6":"1px solid #10b981",borderRadius:6,padding:"3px 10px"}}>
                    {m.food==="empty"?"Empty stomach":m.food==="before"?"Before food":"After food"}
                  </div>
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

