      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
        <div style={{fontSize:16,fontWeight:900,color:"#0a2472",textShadow:"0 1px 6px rgba(10,36,114,0.15)"}}>💊 MEDICINES ({buildCard.meds.length})</div>
        <button onClick={function(){setShowMedPicker(function(v){return !v;});setShowTestPicker(false);}} style={{background:"linear-gradient(135deg,#00CED1,#00B5BB)",border:"none",borderRadius:8,padding:"9px 16px",fontSize:15,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit"}}>{showMedPicker?"▲ Close":"+ Add Medicine"}</button>
      </div>
      {buildCard.meds.length===0&&!showMedPicker&&<div style={{fontSize:15,color:"#0a2472",fontWeight:700,textAlign:"center",padding:"8px"}}>No medicines added yet</div>}
