          {[{key:"morning",label:"🌅 Morn"},{key:"noon",label:"☀️ Noon"},{key:"evening",label:"🌤️ Eve"},{key:"night",label:"🌙 Night"}].map(function(slot){var active=(m.slots||["morning"]).indexOf(slot.key)>=0;return(<button key={slot.key} onClick={function(){toggleMedSlot(i,slot.key);}} style={{flex:1,padding:"7px 4px",fontSize:14,fontWeight:800,borderRadius:6,border:"1.5px solid "+(active?"#22d3ee":"#334155"),background:active?"rgba(34,211,238,0.18)":"transparent",color:active?"#22d3ee":T.sub,cursor:"pointer",fontFamily:"inherit"}}>{slot.label}</button>);})}
