function UnaniPage({T,goBack}){
  const cats=[...new Set(UNANI_MEDS.map(m=>m.cat))];
  const [selCat,setSelCat]=useState("All");
  const [search,setSearch]=useState("");
  const filtered=UNANI_MEDS.filter(m=>(selCat==="All"||m.cat===selCat)&&(m.n.toLowerCase().includes(search.toLowerCase())||m.e.toLowerCase().includes(search.toLowerCase())||m.u.includes(search)||m.ue.toLowerCase().includes(search.toLowerCase())));
  const catColors={"Digestive":"#00CED1","Respiratory":"#38bdf8","Fever":"#ef4444","Skin":"#f59e0b","Nerves":"#8b5cf6","Women":"#ec4899","Musculo":"#f97316","Heart":"#ef4444","Urinary":"#0ea5e9","Male":"#22d3ee","Special":"#a78bfa","Eyes":"#34d399","All":"#16a34a"};
  return (
    <div className="fu" style={{background:T.bg,minHeight:"100vh"}}>
      <ShinyNavHdr titleRaw="🌿 Unani Dawa" sub={`${UNANI_MEDS.length}+ medicines · Hindi & English`} gradient="linear-gradient(160deg,#071b3e,#003035,#00535A)" goBack={goBack}/>
      <div style={{padding:"10px 10px 0"}}>
        <div style={{background:"linear-gradient(135deg,#16a34a22,#38bdf822)",border:"1.5px solid #16a34a55",borderRadius:14,padding:"10px 12px",marginBottom:10}}>
          <div style={{fontSize:11,fontWeight:900,color:"#16a34a",marginBottom:4}}>🌿 यूनानी चिकित्सा</div>
          <div style={{fontSize:13,color:T.sub,lineHeight:1.6}}>Humoral theory · Mizaj (Temperament) · Natural healing · Greek-Arabic medicine · हिंदी और English में दवाइयाँ</div>
        </div>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="🔍 दवा खोजें / Search medicine..." style={{width:"100%",border:`1.5px solid ${T.bor}`,borderRadius:10,padding:"9px 12px",fontSize:11,color:T.text,background:T.card,outline:"none",fontFamily:"inherit",marginBottom:8,boxSizing:"border-box"}}/>
        <div style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:6,marginBottom:8}}>
          {["All",...cats].map(c=><button key={c} onClick={()=>setSelCat(c)} style={{flexShrink:0,padding:"6px 13px",borderRadius:20,border:`1.5px solid ${catColors[c]||"#16a34a"}`,background:selCat===c?catColors[c]||"#16a34a":"transparent",color:selCat===c?"#fff":catColors[c]||"#16a34a",fontSize:11,fontWeight:800,cursor:"pointer",fontFamily:"inherit"}}>{c}</button>)}
        </div>
        <div style={{fontSize:13,color:T.sub,marginBottom:8}}>{filtered.length} दवाइयाँ / medicines</div>
        <div style={{paddingBottom:80}}>
          {filtered.map((m,i)=>(
            <div key={i} className="c3d" style={{background:T.card,border:`1.5px solid ${catColors[m.cat]||T.bor}`,borderRadius:13,padding:"11px 13px",marginBottom:8}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:5}}>
                <div>
                  <div style={{fontSize:16,fontWeight:900,color:T.text}}>{m.n}</div>
                  <div style={{fontSize:13,color:T.sub,fontStyle:"italic",marginTop:1}}>{m.e}</div>
                </div>
                <span style={{fontSize:9,background:`${catColors[m.cat]||"#16a34a"}22`,color:catColors[m.cat]||"#16a34a",borderRadius:20,padding:"2px 8px",fontWeight:800,flexShrink:0}}>{m.cat}</span>
              </div>
              <div style={{background:"rgba(22,163,74,0.06)",borderRadius:8,padding:"7px 9px",marginBottom:5}}>
                <div style={{fontSize:13,fontWeight:800,color:"#16a34a",marginBottom:2}}>🇮🇳 उपयोग</div>
                <div style={{fontSize:13,color:T.text,lineHeight:1.6}}>{m.u}</div>
              </div>
              <div style={{background:"rgba(59,130,246,0.06)",borderRadius:8,padding:"7px 9px"}}>
                <div style={{fontSize:13,fontWeight:800,color:"#38bdf8",marginBottom:2}}>🇬🇧 Uses</div>
                <div style={{fontSize:13,color:T.text,lineHeight:1.6}}>{m.ue}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

