  useEffect(function(){setCatBoxOpen(false);},[categoryDocs]);
  var [view,setView]=useState(function(){
    if(preSelectedDoctor)return "askAppt";           // Direct from FindDoctor Ask button
    if(symptomAutoCard&&initialSymptoms&&initialSymptoms.length>0)return "card";
    return "list";
  }); // list | card | doctorlist | askAppt | paydoc | prescription | medbill | medpaid | labtests | labpaid
  var [apptSelDate,setApptSelDate]=useState(null);
