function PhysiotherapistInfoPage({T,goBack,fbUser,userRole,goTo,setSelDoc,setSharedSymptoms,setSymptomAutoCard}){
  var [mainTab,setMainTab]=useState("doctors");
  const conditions=[
    {icon:"🦴",title:"Back & Spine Pain",desc:"Chronic lower back pain, herniated discs, sciatica, spondylitis, posture-related pain from prolonged sitting/standing."},
    {icon:"🦵",title:"Joint Pain & Arthritis",desc:"Knee pain, osteoarthritis, rheumatoid arthritis, shoulder pain, hip joint problems, ankle sprains."},
    {icon:"💪",title:"Sports & Muscle Injuries",desc:"Ligament tears, muscle strain, rotator cuff injuries, tennis elbow, runner's knee, shin splints, post-exercise recovery."},
    {icon:"🧠",title:"Neurological Conditions",desc:"Stroke rehabilitation, Parkinson's disease mobility, multiple sclerosis, cerebral palsy, nerve pain (neuropathy)."},
    {icon:"🤕",title:"Post-Surgery Rehabilitation",desc:"After orthopedic surgery (knee/hip replacement), fracture healing, post-cardiac surgery, post-spinal surgery mobility."},
    {icon:"👶",title:"Pediatric Conditions",desc:"Developmental delays in children, club foot, juvenile arthritis, cerebral palsy physiotherapy for kids."},
    {icon:"🤰",title:"Women's Health",desc:"Pre & post-natal physiotherapy, pelvic floor strengthening, diastasis recti (post-delivery abdominal gap), lymphedema."},
    {icon:"🫁",title:"Respiratory Conditions",desc:"COPD management, asthma breathing exercises, post-COVID lung recovery, bronchiectasis airway clearance."},
    {icon:"👴",title:"Geriatric Care",desc:"Balance disorders, fall prevention in elderly, osteoporosis management, age-related mobility decline."},
    {icon:"🧘",title:"Workplace & Postural Issues",desc:"Neck pain from screens, carpal tunnel syndrome, repetitive strain injuries, frozen shoulder from sedentary work."},
  ];
  const callWhen=[
    "Persistent pain lasting more than 2 weeks despite rest or medication",
    "Reduced range of motion in any joint — difficulty bending, rotating, or lifting",
    "Recurring sports injuries or muscle pulls",
    "After fracture, surgery or serious injury — for rehab",
    "Weakness or numbness in limbs that affects daily activities",
    "Balance problems or frequent falls",
    "Difficulty walking, climbing stairs or sitting for long",
    "Stiffness in the morning that lasts more than 30 minutes",
    "Breathing difficulty (for chest physio)",
    "Doctor has specifically referred you to physiotherapy",
  ];
  return(
    <div className="fu" style={{background:T.bg,minHeight:"100vh"}}>
      <div style={{background:"linear-gradient(160deg,#0c2a4a,#0369a1,#0ea5e9)",padding:"12px 14px 0",position:"relative",overflow:"hidden"}}>
        <GalaxyBg/>
        <div style={{position:"relative",zIndex:2}}>
          <BackBtn goBack={goBack}/>
          <div style={{fontSize:28,fontWeight:900,color:"#fff",marginTop:4,textShadow:"0 0 16px rgba(255,255,255,0.4)"}}>🦴 Physiotherapist</div>
          <div style={{fontSize:14,color:"rgba(255,255,255,0.9)",marginTop:4,marginBottom:10,fontWeight:700}}>Physical therapy · Movement · Rehabilitation · Pain relief</div>
          <button onClick={function(){if(setSharedSymptoms)setSharedSymptoms(["Physiotherapy consultation","Joint, back or muscle pain, rehabilitation needed"]);if(setSymptomAutoCard)setSymptomAutoCard(true);if(goTo)goTo("symptoms");}} style={{width:"100%",background:"linear-gradient(135deg,#ff6a00,#ff8c00)",border:"none",borderRadius:12,padding:"13px",fontSize:14,fontWeight:900,color:"#fff",cursor:"pointer",fontFamily:"inherit",marginBottom:12,boxShadow:"0 4px 18px rgba(255,106,0,0.45)"}}>📋 Ask Appointment · Choose Symptoms →</button>
        </div>
        <div style={{display:"flex",position:"relative",zIndex:2,borderTop:"1px solid rgba(255,255,255,0.2)"}}>
          {[{k:"doctors",l:"\uD83D\uDC68\u200D\u2695\uFE0F Doctors"},{k:"transparent",l:"\uD83E\uDEB5 Transparent Body"},{k:"mypost",l:"\uD83D\uDCDD My Post"}].map(function(t){
            var act=mainTab===t.k;
            return(<button key={t.k} onClick={function(){setMainTab(t.k);}} style={{flex:1,padding:"13px 4px",background:"none",border:"none",borderBottom:act?"3px solid #60c6ff":"3px solid transparent",fontSize:15,fontWeight:900,color:act?"#60c6ff":"#7cb9e8",cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap",textShadow:act?"0 0 12px rgba(96,198,255,0.95)":"0 0 8px rgba(124,185,232,0.7)"}}>{t.l}</button>);
          })}
        </div>
      </div>
      {mainTab==="doctors"&&<div style={{padding:"14px 14px 80px"}}>
        {(function(){var regd=[];try{regd=JSON.parse(localStorage.getItem("ih_registered_doctors")||"[]").filter(function(d){return d.spec==="Physiotherapist"||d.spec==="Physiotherapy"||d.stream==="Physiotherapy";});}catch(e){}return regd.length>0?(<div style={{marginBottom:6}}><div style={{fontSize:13,fontWeight:800,color:"#00CED1",marginBottom:8}}>🆕 Registered on Infinity Heal</div>{regd.map(function(d,i){return(<div key={"r"+i} style={{background:T.card,border:"1.5px solid #0ea5e9",borderRadius:12,padding:"12px",marginBottom:8}}><div style={{fontSize:14,fontWeight:900,color:T.text}}>{d.name}<span style={{fontSize:10,background:"#00CED133",color:"#00CED1",borderRadius:4,padding:"1px 5px",marginLeft:6}}>New</span></div><div style={{fontSize:12,color:"#0ea5e9",fontWeight:700}}>{d.spec} · {d.city}</div><div style={{fontSize:11,color:T.sub,marginTop:2,marginBottom:8}}>{d.clinic} · {d.fee}</div><button onClick={function(){if(setSharedSymptoms)setSharedSymptoms(["Physiotherapy consultation","Doctor: "+d.name]);if(setSymptomAutoCard)setSymptomAutoCard(true);if(goTo)goTo("symptoms");}} style={{width:"100%",background:"linear-gradient(135deg,#ff6a00,#ff8c00)",border:"none",borderRadius:9,padding:"9px",fontSize:12,fontWeight:800,color:"#fff",cursor:"pointer",fontFamily:"inherit"}}>📋 Ask Appointment</button></div>);})}</div>):null;})()}
        <div className="c3d" style={{background:"linear-gradient(135deg,#0ea5e915,#bae6fd22)",border:"2px solid #0ea5e944",borderRadius:16,padding:"18px 16px",marginBottom:14,textAlign:"center"}}>
          <div style={{fontSize:40}}>🦴</div>
          <div style={{fontSize:20,fontWeight:900,color:"#071b3e",marginTop:8}}>Physiotherapy — Movement is Medicine</div>
          <div style={{fontSize:14,color:T.sub,marginTop:8,lineHeight:1.7}}>
            A physiotherapist (PT) diagnoses and treats physical impairments, promotes mobility, and helps restore function lost due to injury, surgery, disease or aging — without surgery or heavy medication.
          </div>
        </div>

        <div style={{fontSize:15,fontWeight:900,color:T.text,marginBottom:10,marginTop:4}}>🩺 Conditions Physiotherapists Treat</div>
        {conditions.map((c,i)=>(
          <div key={i} className="c3d" style={{background:T.card,border:`1.5px solid ${T.bor}`,borderRadius:13,padding:"12px 14px",marginBottom:8,display:"flex",alignItems:"flex-start",gap:12}}>
            <div style={{fontSize:26,flexShrink:0,marginTop:2}}>{c.icon}</div>
            <div>
              <div style={{fontSize:15,fontWeight:800,color:T.text,marginBottom:3}}>{c.title}</div>
              <div style={{fontSize:13,color:T.sub,lineHeight:1.6}}>{c.desc}</div>
            </div>
          </div>
        ))}

        <div style={{fontSize:16,fontWeight:900,color:"#071b3e",marginBottom:12,marginTop:16}}>📞 When to Call a Physiotherapist</div>
        <div className="c3d" style={{background:"linear-gradient(135deg,#0ea5e908,#bae6fd12)",border:"1.5px solid #0ea5e933",borderRadius:14,padding:"14px 15px",marginBottom:12}}>
          {callWhen.map((w,i)=>(
            <div key={i} style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:i<callWhen.length-1?11:0}}>
              <span style={{color:"#0369a1",fontWeight:900,fontSize:16,marginTop:1,flexShrink:0}}>✓</span>
              <div style={{fontSize:13,color:T.sub,lineHeight:1.6}}>{w}</div>
            </div>
          ))}
        </div>

        <div className="c3d" style={{background:"linear-gradient(135deg,#fef9c3,#fef08a22)",border:"2px solid #fbbf2444",borderRadius:13,padding:"13px 14px",marginBottom:10}}>
          <div style={{fontSize:15,fontWeight:900,color:"#92400e",marginBottom:6}}>💡 Did You Know?</div>
          <div style={{fontSize:13,color:T.sub,lineHeight:1.65}}>
            Physiotherapy is recommended BEFORE surgery in many cases — studies show that "pre-hab" (pre-operative physiotherapy) significantly improves post-surgery recovery speed and outcomes. Always consult a PT alongside your orthopedic doctor.
          </div>
        </div>

        <div className="c3d" style={{background:"linear-gradient(135deg,#0369a115,#0ea5e918)",border:"2px solid #0ea5e966",borderRadius:14,padding:"13px 14px"}}>
          <div style={{fontSize:15,fontWeight:900,color:"#071b3e",marginBottom:8}}>🏥 Types of Physiotherapy</div>
          {[
            {t:"Orthopedic PT",d:"Bones, muscles, joints, ligaments — most common type"},
            {t:"Neurological PT",d:"Brain & nerve disorders — stroke, Parkinson's, MS"},
            {t:"Cardiopulmonary PT",d:"Heart & lung recovery — post-cardiac surgery, COPD"},
            {t:"Pediatric PT",d:"Child developmental disorders, cerebral palsy, scoliosis"},
            {t:"Sports PT",d:"Injury prevention, athlete rehabilitation, performance recovery"},
            {t:"Geriatric PT",d:"Elderly mobility, fall prevention, arthritis management"},
            {t:"Women's Health PT",d:"Pelvic floor rehab, pre/post-natal care, diastasis recti, incontinence, lymphedema"},
            {t:"Vestibular PT",d:"Balance disorders, BPPV vertigo, dizziness, Epley manoeuvre, inner ear rehab"},
            {t:"Aquatic PT",d:"Hydrotherapy pool exercises — reduces joint load, ideal for arthritis, obesity, post-surgery"},
            {t:"Oncology PT",d:"Cancer rehabilitation — fatigue management, lymphedema, post-mastectomy mobility, strength restoration"},
            {t:"Occupational Rehab PT",d:"Return-to-work programmes, repetitive strain, ergonomic retraining, hand/wrist function after injury"},
          ].map((tp,i)=>(
            <div key={i} style={{display:"flex",gap:8,alignItems:"flex-start",marginBottom:i<10?7:0}}>
              <span style={{fontWeight:900,color:"#0ea5e9",flexShrink:0,marginTop:1}}>•</span>
              <div>
                <span style={{fontSize:14,fontWeight:900,color:"#071b3e"}}>{tp.t}: </span>
                <span style={{fontSize:13,color:T.sub}}>{tp.d}</span>
              </div>
            </div>
          ))}
        </div>
      </div>}
      {mainTab==="transparent"&&<div style={{minHeight:"80vh"}}/>}
      {mainTab==="mypost"&&(<MyPostSocialPage T={T} goBack={function(){setMainTab("doctors");}} fbUser={fbUser} userRole={userRole} onLogout={function(){}}/>)}
    </div>
  );
}

